"""Integrate completed external experiments, with their actual scope and limits."""
from pathlib import Path
import json, re, html
import numpy as np


def evidence(root):
    return {k:json.loads((Path(root)/'results/extended'/f'{k}.json').read_text())
            for k in ['published','external_dataset','sequences','mapping_external','external_raw','optimization','group_cv','residual','external_comparators','external_raw_candidates']}


def integrate_extended(text, root):
    from build_manuscript import table, esc, pc, num
    e=evidence(root);p=e['published'];d=e['external_dataset'];s=e['sequences'];m=e['mapping_external'];r=e['external_raw']
    transfer=d['transfer']['models']['X-ERD'];raw=r['models']['X-ERD']
